package api

// englishJLPTSimulationExtraExplanations translates the explanations of the free
// JLPT N5 and N4 practice papers 02-05 (papers 06+ carry English in their JSON). Japanese examples are preserved exactly.
var englishJLPTSimulationExtraExplanations = map[examSSWEnglishKey]string{
	{field: "simulation.explanation", source: "毎週 dibaca まいしゅう, setiap minggu. 毎日 (まいにち) = setiap hari; 毎月 (まいつき) = setiap bulan; 毎年 (まいとし) = setiap tahun."}:                                                      "毎週 is read まいしゅう, meaning every week. 毎日 (まいにち) = every day; 毎月 (まいつき) = every month; 毎年 (まいとし) = every year.",
	{field: "simulation.explanation", source: "大学 dibaca だいがく (universitas). 大 pada kata ini dibaca だい dan 学 dibaca がく."}:                                                                                          "大学 is read だいがく (university). In this word 大 is read だい and 学 is read がく.",
	{field: "simulation.explanation", source: "新聞 dibaca しんぶん (koran). 聞 pada kata ini dibaca ぶん, bukan もん."}:                                                                                                      "新聞 is read しんぶん (newspaper). In this word 聞 is read ぶん, not もん.",
	{field: "simulation.explanation", source: "雨 dibaca あめ (hujan). 雪 = ゆき (salju); 風 = かぜ (angin); 雲 = くも (awan)."}:                                                                                               "雨 is read あめ (rain). 雪 = ゆき (snow); 風 = かぜ (wind); 雲 = くも (cloud).",
	{field: "simulation.explanation", source: "九時 dibaca くじ (pukul sembilan). Pada penyebutan jam, 九 dibaca く, bukan きゅう."}:                                                                                        "九時 is read くじ (nine o'clock). When telling the time, 九 is read く, not きゅう.",
	{field: "simulation.explanation", source: "立つ (たつ) berarti berdiri; bentuk て menjadi 立って (たって). 乗って = naik; 買って = membeli; 待って = menunggu."}:                                                                   "立つ (たつ) means to stand; its て-form is 立って (たって). 乗って = riding; 買って = buying; 待って = waiting.",
	{field: "simulation.explanation", source: "二十日 dibaca はつか, tanggal 20. Tanggal 20 memiliki bacaan khusus; 二日 = ふつか adalah tanggal 2."}:                                                                         "二十日 is read はつか, the 20th of the month. The 20th has a special reading; 二日 = ふつか is the 2nd.",
	{field: "simulation.explanation", source: "でんわ (telepon) ditulis 電話. 電 berarti listrik dan 話 berarti berbicara."}:                                                                                              "でんわ (telephone) is written 電話. 電 means electricity and 話 means to talk.",
	{field: "simulation.explanation", source: "かわ (sungai) ditulis 川. 山 = gunung; 小 = kecil; 月 = bulan."}:                                                                                                          "かわ (river) is written 川. 山 = mountain; 小 = small; 月 = moon or month.",
	{field: "simulation.explanation", source: "きた (utara) ditulis 北. 比, 化, dan 兆 adalah huruf lain yang bentuknya mirip."}:                                                                                         "きた (north) is written 北. 比, 化 and 兆 are other characters with a similar shape.",
	{field: "simulation.explanation", source: "あたらしい (baru) ditulis 新しい. 親, 近, dan 古 masing-masing berarti orang tua/akrab, dekat, dan lama; bukan tulisan あたらしい."}:                                                "あたらしい (new) is written 新しい. 親, 近 and 古 mean parent/close, near and old respectively; they are not how あたらしい is written.",
	{field: "simulation.explanation", source: "ほてる (hotel) ditulis ホテル dalam katakana. ホデル, ホテレ, dan ポテル bukan ejaan yang benar."}:                                                                                 "ほてる (hotel) is written ホテル in katakana. ホデル, ホテレ and ポテル are not correct spellings.",
	{field: "simulation.explanation", source: "かおをあらう berarti mencuci muka. きる = memotong; ひく = menarik atau memainkan; かける = menggantungkan atau memakai kacamata."}:                                              "かおをあらう means to wash one's face. きる = to cut; ひく = to pull or to play (an instrument); かける = to hang or to wear glasses.",
	{field: "simulation.explanation", source: "Ruangan panas, maka jendela dibuka: まどをあける. しめる = menutup; けす = mematikan; つける = menyalakan."}:                                                                      "The room is hot, so you open the window: まどをあける. しめる = to close; けす = to turn off; つける = to turn on.",
	{field: "simulation.explanation", source: "Cuaca bagus, maka berjalan-jalan di taman: こうえんをさんぽする. せんたく = mencuci pakaian; かいもの = berbelanja; しゅくだい = pekerjaan rumah."}:                                        "The weather is nice, so you take a walk in the park: こうえんをさんぽする. せんたく = doing laundry; かいもの = shopping; しゅくだい = homework.",
	{field: "simulation.explanation", source: "せがたかい berarti bertubuh tinggi. ながい dipakai untuk benda panjang; ひろい = luas; おそい = lambat."}:                                                                         "せがたかい means to be tall. ながい is used for long objects; ひろい = wide; おそい = slow.",
	{field: "simulation.explanation", source: "つかれた berarti lelah, maka beristirahat sebentar: 休みましょう. ならぶ = berbaris; はしる = berlari; ならう = belajar."}:                                                             "つかれた means tired, so you rest for a while: 休みましょう. ならぶ = to line up; はしる = to run; ならう = to learn.",
	{field: "simulation.explanation", source: "Salam pagi ketika bertemu guru adalah おはようございます. おやすみなさい dipakai sebelum tidur; いってきます saat berangkat dari rumah; いただきます sebelum makan."}:                           "The morning greeting when you meet your teacher is おはようございます. おやすみなさい is said before sleeping; いってきます when leaving home; いただきます before eating.",
	{field: "simulation.explanation", source: "ちかくです berarti dekat, sehingga padanannya adalah tidak begitu jauh. Pilihan lain berarti sangat jauh, di dalam sekolah, atau pergi naik pesawat."}:                   "ちかくです means it is near, so the equivalent is not very far. The other choices mean very far, inside the school, or going by airplane.",
	{field: "simulation.explanation", source: "ひとりで berarti sendirian, tanpa ditemani siapa pun. Pilihan lain berarti pergi bersama teman, tidak berbelanja sama sekali, atau tinggal di rumah bersama keluarga."}: "ひとりで means alone, with no one accompanying you. The other choices mean going with a friend, not shopping at all, or staying home with family.",
	{field: "simulation.explanation", source: "Karena besok hujan, tidak pergi berjalan-jalan. Jawaban benar menyatakan sebab dan akibat yang sama; pilihan lain berlawanan."}:                                     "Because it will rain tomorrow, you will not go for a walk. The correct answer states the same cause and effect; the other choices contradict it.",
	{field: "simulation.explanation", source: "Titik awal ditandai から: 駅から学校まで berarti dari stasiun sampai sekolah. Pasangannya adalah まで."}:                                                                       "The starting point is marked with から: 駅から学校まで means from the station to the school. Its partner is まで.",
	{field: "simulation.explanation", source: "Perbandingan memakai より: 私より背が高い berarti lebih tinggi daripada saya. ほど dipakai dengan bentuk negatif."}:                                                            "Comparison uses より: 私より背が高い means taller than me. ほど is used with the negative form.",
	{field: "simulation.explanation", source: "すき memakai partikel が untuk hal yang disukai: ねこがすきです."}:                                                                                                            "すき takes the particle が for the thing that is liked: ねこがすきです.",
	{field: "simulation.explanation", source: "Bentuk て + はいけません menyatakan larangan: とってはいけません, tidak boleh mengambil foto."}:                                                                                     "The て-form + はいけません expresses prohibition: とってはいけません means you must not take photos.",
	{field: "simulation.explanation", source: "Bentuk た + あとで berarti setelah melakukan sesuatu: setelah makan, minum obat. まえに memakai bentuk kamus."}:                                                            "The た-form + あとで means after doing something: after eating, take medicine. まえに is used with the dictionary form.",
	{field: "simulation.explanation", source: "Bentuk て + います menyatakan tindakan yang sedang berlangsung: おしえています, sedang mengajar."}:                                                                             "The て-form + います expresses an action in progress: おしえています means is teaching.",
	{field: "simulation.explanation", source: "Permintaan agar tidak melakukan sesuatu: bentuk ない + でください, yaitu すわないでください (tolong jangan merokok)."}:                                                              "A request not to do something: ない-form + でください, that is, すわないでください (please do not smoke).",
	{field: "simulation.explanation", source: "Kata tanya + も + bentuk negatif berarti tidak ... mana pun: どこへもいきませんでした, tidak pergi ke mana pun."}:                                                                "Question word + も + negative means not ... anywhere: どこへもいきませんでした means did not go anywhere.",
	{field: "simulation.explanation", source: "しんせつ adalah kata sifat な. Sebelum kata benda dipakai な: しんせつな人."}:                                                                                                   "しんせつ is a な-adjective. Before a noun, な is used: しんせつな人.",
	{field: "simulation.explanation", source: "Urutan: これは ともだちが りょこうで とった しゃしんです (ini foto yang diambil teman saat bepergian). ★ adalah slot ketiga, とった."}:                                                       "Order: これは ともだちが りょこうで とった しゃしんです (this is a photo my friend took on a trip). ★ is the third slot, とった.",
	{field: "simulation.explanation", source: "Urutan: ごはんを たべてから くすりを のんで ください (setelah makan, minumlah obat). ★ adalah slot ketiga, くすりを."}:                                                                      "Order: ごはんを たべてから くすりを のんで ください (please take the medicine after eating). ★ is the third slot, くすりを.",
	{field: "simulation.explanation", source: "Urutan: あの めがねを かけて いる ひとは わたしの ともだちです (orang berkacamata itu teman saya). ★ adalah slot ketiga, いる."}:                                                              "Order: あの めがねを かけて いる ひとは わたしの ともだちです (that person wearing glasses is my friend). ★ is the third slot, いる.",
	{field: "simulation.explanation", source: "Urutan: わたしは うたを うたう のが すきです (saya suka bernyanyi). ★ adalah slot kedua, うたう."}:                                                                                     "Order: わたしは うたを うたう のが すきです (I like singing). ★ is the second slot, うたう.",
	{field: "simulation.explanation", source: "Pergi bersama teman memakai と: ともだちとこうえんへいきました."}:                                                                                                                   "Going together with a friend uses と: ともだちとこうえんへいきました.",
	{field: "simulation.explanation", source: "Kalimat sebelumnya dan sesudahnya adalah rangkaian kegiatan, maka そして tepat. でも menyatakan pertentangan; ですから sebab-akibat; ところで pergantian topik."}:                "The sentences before and after describe a series of activities, so そして fits. でも expresses contrast; ですから cause and effect; ところで a change of topic.",
	{field: "simulation.explanation", source: "Kejadiannya kemarin, maka kata sifat い dalam bentuk lampau sopan: おいしかったです. おいしいでした dan おいしくでした tidak benar."}:                                                      "It happened yesterday, so the い-adjective takes the polite past form: おいしかったです. おいしいでした and おいしくでした are incorrect.",
	{field: "simulation.explanation", source: "Cerita tentang kemarin memakai bentuk lampau: かえりました, pulang ke rumah."}:                                                                                            "A story about yesterday uses the past form: かえりました, went home.",
	{field: "simulation.explanation", source: "駅 dibaca えき (stasiun). Pilihan lain bukan bacaan kanji tersebut."}:                                                                                                  "駅 is read えき (station). The other choices are not readings of that kanji.",
	{field: "simulation.explanation", source: "来週 dibaca らいしゅう, minggu depan. 先週 = せんしゅう (minggu lalu); 今週 = こんしゅう (minggu ini); 来月 = らいげつ (bulan depan)."}:                                                        "来週 is read らいしゅう, next week. 先週 = せんしゅう (last week); 今週 = こんしゅう (this week); 来月 = らいげつ (next month).",
	{field: "simulation.explanation", source: "食べる (たべる) berarti makan; bentuk sopannya 食べます (たべます)."}:                                                                                                             "食べる (たべる) means to eat; its polite form is 食べます (たべます).",
	{field: "simulation.explanation", source: "小さい dibaca ちいさい (kecil). Perhatikan い panjang pada ちいさい."}:                                                                                                          "小さい is read ちいさい (small). Note the long い in ちいさい.",
	{field: "simulation.explanation", source: "十分 dibaca じゅっぷん, sepuluh menit. 分 setelah 十 berubah menjadi っぷん. じゅうぶん (十分) berarti cukup, tetapi artinya berbeda."}:                                                "十分 is read じゅっぷん, ten minutes. 分 after 十 changes to っぷん. じゅうぶん (十分) means enough, but its meaning is different.",
	{field: "simulation.explanation", source: "姉 dibaca あね, kakak perempuan sendiri. 兄 = あに (kakak laki-laki); 妹 = いもうと (adik perempuan); 母 = はは (ibu)."}:                                                          "姉 is read あね, one's own older sister. 兄 = あに (older brother); 妹 = いもうと (younger sister); 母 = はは (mother).",
	{field: "simulation.explanation", source: "名前 dibaca なまえ (nama). 名 dibaca な dan 前 dibaca まえ."}:                                                                                                                 "名前 is read なまえ (name). 名 is read な and 前 is read まえ.",
	{field: "simulation.explanation", source: "にほんご (bahasa Jepang) ditulis 日本語. 日 dan 本 membentuk にほん; 語 berarti bahasa."}:                                                                                        "にほんご (the Japanese language) is written 日本語. 日 and 本 form にほん; 語 means language.",
	{field: "simulation.explanation", source: "ともだち (teman) ditulis 友達. Pilihan lain memakai huruf yang bentuknya mirip tetapi bukan tulisan yang benar."}:                                                         "ともだち (friend) is written 友達. The other choices use look-alike characters but are not the correct spelling.",
	{field: "simulation.explanation", source: "あかい (merah) ditulis 赤い. 青い dibaca あおい (biru); 白い dibaca しろい (putih); 亦 bukan huruf untuk kata ini."}:                                                                "あかい (red) is written 赤い. 青い is read あおい (blue); 白い is read しろい (white); 亦 is not a character for this word.",
	{field: "simulation.explanation", source: "ろくがつ (bulan Juni) ditulis 六月. 八月 = はちがつ (Agustus); 六日 dibaca むいか (tanggal 6)."}:                                                                                     "ろくがつ (June) is written 六月. 八月 = はちがつ (August); 六日 is read むいか (the 6th).",
	{field: "simulation.explanation", source: "てれび ditulis テレビ dalam katakana. Tanda dakuten (゛) harus pada ヒ menjadi ビ, dan tidak ada ー di akhir kata ini."}:                                                      "てれび is written テレビ in katakana. The dakuten (゛) must be on ヒ to make ビ, and this word has no ー at the end.",
	{field: "simulation.explanation", source: "Pakaian di badan memakai きる: コートをきる. はく = mengenakan sepatu atau celana; かぶる = memakai topi; かける = memakai kacamata."}:                                              "Clothes on the body use きる: コートをきる. はく = to put on shoes or trousers; かぶる = to put on a hat; かける = to put on glasses.",
	{field: "simulation.explanation", source: "Harga satu jam tangan sepuluh ribu yen terasa mahal: たかい. おもい = berat; ひろい = luas; ながい = panjang."}:                                                                 "A watch costing ten thousand yen feels expensive: たかい. おもい = heavy; ひろい = wide; ながい = long.",
	{field: "simulation.explanation", source: "Besok ujian, maka hari ini belajar di rumah: べんきょうします. Pilihan lain tidak berkaitan dengan persiapan ujian."}:                                                       "There is an exam tomorrow, so you study at home today: べんきょうします. The other choices have nothing to do with exam preparation.",
	{field: "simulation.explanation", source: "くすりをもらう berarti menerima obat. ならう = belajar; かりる = meminjam; おぼえる = mengingat."}:                                                                                   "くすりをもらう means to receive medicine. ならう = to learn; かりる = to borrow; おぼえる = to remember.",
	{field: "simulation.explanation", source: "電話がなる berarti telepon berdering. ひく = menarik; うる = menjual; きる = memotong atau memutus."}:                                                                          "電話がなる means the phone rings. ひく = to pull; うる = to sell; きる = to cut or hang up.",
	{field: "simulation.explanation", source: "おきる berarti bangun tidur. おぼえる = mengingat; おわる = selesai; おちる = jatuh."}:                                                                                           "おきる means to wake up. おぼえる = to remember; おわる = to finish; おちる = to fall.",
	{field: "simulation.explanation", source: "せまい berarti sempit, sehingga padanannya adalah tidak luas. Pilihan lain berarti sangat luas, terang, atau hangat."}:                                                 "せまい means narrow or small in area, so the equivalent is not spacious. The other choices mean very spacious, bright or warm.",
	{field: "simulation.explanation", source: "じょうず berarti pandai. うまい juga berarti pandai, sehingga maknanya sama. Pilihan lain berarti tidak suka, tidak pandai, atau tidak memasak."}:                          "じょうず means skilled. うまい also means skilled, so the meaning is the same. The other choices mean dislikes, is not good at, or does not cook.",
	{field: "simulation.explanation", source: "やすみ berarti libur, sehingga besok tidak bekerja. Pilihan lain berarti ada pekerjaan, berbicara tentang kemarin, atau ingin bekerja."}:                               "やすみ means a day off, so tomorrow you do not work. The other choices mean there is work, talking about yesterday, or wanting to work.",
	{field: "simulation.explanation", source: "Sarana transportasi ditandai で: 電車で berarti naik kereta."}:                                                                                                          "A means of transport is marked with で: 電車で means by train.",
	{field: "simulation.explanation", source: "Kata tanya + も + bentuk negatif berarti tidak ... apa pun: なにもたべませんでした, tidak makan apa pun."}:                                                                      "Question word + も + negative means not ... anything: なにもたべませんでした means did not eat anything.",
	{field: "simulation.explanation", source: "と menghubungkan benda yang disebut lengkap: つくえといすがあります, ada meja dan kursi."}:                                                                                      "と connects items when all of them are named: つくえといすがあります means there are a desk and a chair.",
	{field: "simulation.explanation", source: "Kemampuan memakai bentuk kamus + ことができます: はなすことができます, dapat berbicara."}:                                                                                            "Ability uses the dictionary form + ことができます: はなすことができます means can speak.",
	{field: "simulation.explanation", source: "Bentuk て + います menyatakan keadaan yang sedang berlangsung: ふっています, sedang turun hujan."}:                                                                            "The て-form + います expresses a continuing state: ふっています means it is raining.",
	{field: "simulation.explanation", source: "Saya memberi bunga kepada teman: あげました. くれました berarti orang lain memberi kepada saya; もらいました berarti menerima."}:                                                    "I gave flowers to a friend: あげました. くれました means someone gave to me; もらいました means received.",
	{field: "simulation.explanation", source: "Keinginan dinyatakan dengan batang ます + たい: いきたいです, ingin pergi."}:                                                                                                  "Desire is expressed with the ます-stem + たい: いきたいです means want to go.",
	{field: "simulation.explanation", source: "Alasan dinyatakan dengan から: さむいから berarti karena dingin. のに menyatakan pertentangan."}:                                                                             "A reason is expressed with から: さむいから means because it is cold. のに expresses contrast.",
	{field: "simulation.explanation", source: "Pada pertanyaan perbandingan dipakai どちらが: Mana yang lebih disukai, anjing atau kucing?"}:                                                                           "Comparison questions use どちらが: Which do you like better, dogs or cats?",
	{field: "simulation.explanation", source: "Urutan: これは おとうとが きのう かった かばんです (ini tas yang dibeli adik kemarin). ★ adalah slot ketiga, かった."}:                                                                    "Order: これは おとうとが きのう かった かばんです (this is the bag my younger brother bought yesterday). ★ is the third slot, かった.",
	{field: "simulation.explanation", source: "Urutan: あの ギターを ひいて いる ひとは わたしの ともだちです (orang yang bermain gitar itu teman saya). ★ adalah slot kedua, ひいて."}:                                                       "Order: あの ギターを ひいて いる ひとは わたしの ともだちです (that person playing the guitar is my friend). ★ is the second slot, ひいて.",
	{field: "simulation.explanation", source: "Urutan: この みせは あさ 九じから よる 十じまでです (toko ini buka dari pukul 9 pagi sampai pukul 10 malam). ★ adalah slot ketiga, よる."}:                                               "Order: この みせは あさ 九じから よる 十じまでです (this shop is open from 9 a.m. to 10 p.m.). ★ is the third slot, よる.",
	{field: "simulation.explanation", source: "Urutan: わたしは あした ともだちと えいがを みに いきたいです (besok saya ingin pergi menonton film bersama teman). ★ adalah slot keempat, みに."}:                                            "Order: わたしは あした ともだちと えいがを みに いきたいです (tomorrow I want to go see a movie with a friend). ★ is the fourth slot, みに.",
	{field: "simulation.explanation", source: "あした (besok) berarti kejadian di masa depan, maka bentuk non-lampau: きます, akan datang."}:                                                                             "あした (tomorrow) refers to the future, so the non-past form is used: きます, will come.",
	{field: "simulation.explanation", source: "Bentuk て + います menyatakan sedang berlangsung: つくっています, sedang membuat kue."}:                                                                                        "The て-form + います expresses an action in progress: つくっています means is making a cake.",
	{field: "simulation.explanation", source: "Teman datang pukul enam, karena itu kue dibuat sebelumnya: ですから menyatakan sebab-akibat. でも dan しかし menyatakan pertentangan."}:                                      "Friends are coming at six, so the cake is made beforehand: ですから expresses cause and effect. でも and しかし express contrast.",
	{field: "simulation.explanation", source: "Pola と + おもいます menyatakan pendapat atau harapan: おいしくできるとおもいます, saya pikir akan enak."}:                                                                             "The pattern と + おもいます expresses an opinion or hope: おいしくできるとおもいます means I think it will turn out delicious.",
	{field: "simulation.explanation", source: "午前 dibaca ごぜん (pagi hari, sebelum tengah hari). 午後 (ごご) adalah sore hari."}:                                                                                         "午前 is read ごぜん (morning, before noon). 午後 (ごご) is the afternoon.",
	{field: "simulation.explanation", source: "夏 dibaca なつ (musim panas). 冬 = ふゆ (dingin); 春 = はる (semi); 秋 = あき (gugur)."}:                                                                                        "夏 is read なつ (summer). 冬 = ふゆ (winter); 春 = はる (spring); 秋 = あき (autumn).",
	{field: "simulation.explanation", source: "色 dibaca いろ (warna). Pilihan lain bukan bacaan kanji ini."}:                                                                                                         "色 is read いろ (color). The other choices are not readings of this kanji.",
	{field: "simulation.explanation", source: "図書館 dibaca としょかん (perpustakaan). Tidak ada bunyi panjang pada としょ."}:                                                                                                "図書館 is read としょかん (library). There is no long vowel in としょ.",
	{field: "simulation.explanation", source: "右 dibaca みぎ (kanan). 左 = ひだり (kiri); 上 = うえ (atas)."}:                                                                                                               "右 is read みぎ (right). 左 = ひだり (left); 上 = うえ (up).",
	{field: "simulation.explanation", source: "少し dibaca すこし (sedikit; sebentar). 少 dalam kata ini dibaca すこ."}:                                                                                                    "少し is read すこし (a little; for a moment). In this word 少 is read すこ.",
	{field: "simulation.explanation", source: "病院 dibaca びょういん (rumah sakit). Perhatikan びょう dengan ょ kecil dan う panjang."}:                                                                                       "病院 is read びょういん (hospital). Note びょう with a small ょ and the long う.",
	{field: "simulation.explanation", source: "がっこう (sekolah) ditulis 学校. Pilihan lain memakai huruf yang bentuknya mirip."}:                                                                                       "がっこう (school) is written 学校. The other choices use look-alike characters.",
	{field: "simulation.explanation", source: "やすい (murah) ditulis 安い. 守, 宇, dan 妥 hanya mirip bentuknya."}:                                                                                                        "やすい (cheap) is written 安い. 守, 宇 and 妥 only look similar.",
	{field: "simulation.explanation", source: "ひがし (timur) ditulis 東. 束 (たば) bentuknya mirip; 西 dibaca にし (barat)."}:                                                                                               "ひがし (east) is written 東. 束 (たば) looks similar; 西 is read にし (west).",
	{field: "simulation.explanation", source: "おんがく (musik) ditulis 音楽. 薬 berarti obat, bukan musik."}:                                                                                                             "おんがく (music) is written 音楽. 薬 means medicine, not music.",
	{field: "simulation.explanation", source: "かめら (kamera) ditulis カメラ dalam katakana. Pilihan lain bukan ejaan yang benar."}:                                                                                     "かめら (camera) is written カメラ in katakana. The other choices are not correct spellings.",
	{field: "simulation.explanation", source: "シャツをぬぐ berarti melepas baju. きる = memakai baju; はく = memakai sepatu atau celana; かぶる = memakai topi."}:                                                              "シャツをぬぐ means to take off a shirt. きる = to put on a shirt; はく = to put on shoes or trousers; かぶる = to put on a hat.",
	{field: "simulation.explanation", source: "Kue yang banyak gulanya terasa manis: あまい. からい = pedas; いたい = sakit; ひくい = rendah."}:                                                                                "A cake with a lot of sugar tastes sweet: あまい. からい = spicy; いたい = painful; ひくい = low.",
	{field: "simulation.explanation", source: "しんぶんをよむ berarti membaca koran; bentuk て-nya よんで. のむ = minum; すむ = tinggal; あそぶ = bermain."}:                                                                         "しんぶんをよむ means to read the newspaper; its て-form is よんで. のむ = to drink; すむ = to live; あそぶ = to play.",
	{field: "simulation.explanation", source: "つくえをおく berarti menaruh meja. ひく = menarik; きる = memotong; なる = menjadi."}:                                                                                           "つくえをおく means to put a desk somewhere. ひく = to pull; きる = to cut; なる = to become.",
	{field: "simulation.explanation", source: "かさをさす berarti memakai (membuka) payung. かける = menggantung atau memakai kacamata; かぶる = topi; はく = sepatu."}:                                                         "かさをさす means to use (open) an umbrella. かける = to hang or wear glasses; かぶる = hat; はく = shoes.",
	{field: "simulation.explanation", source: "しらべる berarti memeriksa atau mencari tahu. ならう = belajar dari seseorang; わかる = mengerti; おぼえる = mengingat."}:                                                         "しらべる means to look up or check. ならう = to learn from someone; わかる = to understand; おぼえる = to memorize.",
	{field: "simulation.explanation", source: "とおい berarti jauh, jadi padanannya adalah tidak dekat. Pilihan lain berarti ada stasiun di dekat rumah, rumah di dalam stasiun, atau membeli rumah di stasiun."}:     "とおい means far, so the equivalent is not near. The other choices mean there is a station near the house, the house is inside the station, or buying a house at the station.",
	{field: "simulation.explanation", source: "おもしろくない berarti tidak menarik, sama dengan つまらない. Pilihan lain berarti sangat menarik, tidak ditonton, atau belum ditonton."}:                                       "おもしろくない means not interesting, the same as つまらない. The other choices mean very interesting, did not watch it, or have not watched it yet.",
	{field: "simulation.explanation", source: "Ayah memberi saya buku = saya menerima buku dari ayah. Pilihan lain membalik arah pemberian atau berbeda isi."}:                                                     "Father gave me a book = I received a book from Father. The other choices reverse the direction of giving or change the content.",
	{field: "simulation.explanation", source: "Bentuk lampau + もの berarti benda yang ...: もらったもの, barang yang diterima."}:                                                                                          "Past form + もの means the thing that ...: もらったもの, the thing I received.",
	{field: "simulation.explanation", source: "Mempersilakan seseorang dengan どうぞ. どうも = terima kasih (singkat); ぜひ = sangat ingin; すぐ = segera."}:                                                                 "どうぞ is used to invite someone to go ahead. どうも = thanks (short); ぜひ = by all means; すぐ = right away.",
	{field: "simulation.explanation", source: "Perbandingan: AよりBのほうが... berarti B lebih ... daripada A. ほど dipakai dengan bentuk negatif."}:                                                                       "Comparison: AよりBのほうが... means B is more ... than A. ほど is used with the negative form.",
	{field: "simulation.explanation", source: "まだ + Vていません berarti belum melakukan: まだしゅくだいをしていません."}:                                                                                                              "まだ + Vていません means have not done yet: まだしゅくだいをしていません.",
	{field: "simulation.explanation", source: "から menyatakan alasan: cuaca bagus, jadi mari berjalan-jalan. でも = tetapi; まで = sampai; より = daripada."}:                                                             "から expresses a reason: the weather is nice, so let's take a walk. でも = but; まで = until; より = than.",
	{field: "simulation.explanation", source: "Permintaan memakai bentuk て + ください: まってください (tolong tunggu)."}:                                                                                                      "A request uses the て-form + ください: まってください (please wait).",
	{field: "simulation.explanation", source: "Menyambung kata sifat な dengan で: じょうずで (pandai, dan ...)."}:                                                                                                        "A な-adjective is connected with で: じょうずで (is good at it, and ...).",
	{field: "simulation.explanation", source: "Jumlah + も menekankan bahwa jumlahnya banyak: さんかいも, sampai tiga kali."}:                                                                                            "Quantity + も emphasizes that the amount is large: さんかいも, as many as three times.",
	{field: "simulation.explanation", source: "Pola ～たり～たりします: みたり、よんだりします (menonton ..., membaca ..., dan sebagainya)."}:                                                                                          "The pattern ～たり～たりします: みたり、よんだりします (do things like watching ... and reading ...).",
	{field: "simulation.explanation", source: "Urutan: わたしは あの みせで かった ケーキが すきです (saya suka kue yang dibeli di toko itu). ★ adalah slot ketiga, かった."}:                                                             "Order: わたしは あの みせで かった ケーキが すきです (I like the cake I bought at that shop). ★ is the third slot, かった.",
	{field: "simulation.explanation", source: "Urutan: ここに あなたの なまえと じゅうしょを かいて ください (tolong tulis nama dan alamat Anda di sini). ★ adalah slot ketiga, じゅうしょを."}:                                                  "Order: ここに あなたの なまえと じゅうしょを かいて ください (please write your name and address here). ★ is the third slot, じゅうしょを.",
	{field: "simulation.explanation", source: "Urutan: さとうさんは えいごの うたを うたう のが じょうずです (Pak Sato pandai menyanyikan lagu bahasa Inggris). ★ adalah slot ketiga, うたう."}:                                               "Order: さとうさんは えいごの うたを うたう のが じょうずです (Mr. Sato is good at singing English songs). ★ is the third slot, うたう.",
	{field: "simulation.explanation", source: "Urutan: これは わたしが うまれた まちの しゃしんです (ini foto kota tempat saya lahir). ★ adalah slot ketiga, まちの."}:                                                                    "Order: これは わたしが うまれた まちの しゃしんです (this is a photo of the town where I was born). ★ is the third slot, まちの.",
	{field: "simulation.explanation", source: "Arah tujuan ditandai へ: ともだちのいえへあそびにいきました."}:                                                                                                                        "The destination is marked with へ: ともだちのいえへあそびにいきました.",
	{field: "simulation.explanation", source: "Ceritanya tentang kemarin, maka bentuk lampau: つくりました (membuat)."}:                                                                                                  "The story is about yesterday, so the past form is used: つくりました (made).",
	{field: "simulation.explanation", source: "Kalimat berikutnya adalah kegiatan sesudah makan, maka それから (setelah itu). でも = tetapi; ですから = karena itu; ところで = ngomong-ngomong."}:                                "The next sentence is an activity after the meal, so それから (after that) fits. でも = but; ですから = therefore; ところで = by the way.",
	{field: "simulation.explanation", source: "Minggu depan adalah masa depan; keinginan dinyatakan dengan batang ます + たい: つくりたいです. Pilihan lain bentuk lampau."}:                                                  "Next week is in the future; a wish is expressed with the ます-stem + たい: つくりたいです. The other choices are past forms.",
	{field: "simulation.explanation", source: "朝 dibaca あさ (pagi). 昼 = ひる (siang); 夜 = よる (malam)."}:                                                                                                               "朝 is read あさ (morning). 昼 = ひる (noon); 夜 = よる (night).",
	{field: "simulation.explanation", source: "外 dibaca そと (luar). Lawan katanya adalah 中 (なか, dalam)."}:                                                                                                           "外 is read そと (outside). Its opposite is 中 (なか, inside).",
	{field: "simulation.explanation", source: "忙しい dibaca いそがしい (sibuk). Perhatikan が bertanda dakuten."}:                                                                                                          "忙しい is read いそがしい (busy). Note the が with dakuten.",
	{field: "simulation.explanation", source: "電気 dibaca でんき (listrik; lampu). 天気 dibaca てんき (cuaca)."}:                                                                                                            "電気 is read でんき (electricity; light). 天気 is read てんき (weather).",
	{field: "simulation.explanation", source: "古い dibaca ふるい (tua; lama). Lawan katanya 新しい (あたらしい)."}:                                                                                                             "古い is read ふるい (old). Its opposite is 新しい (あたらしい).",
	{field: "simulation.explanation", source: "外国 dibaca がいこく (luar negeri). 外 dibaca がい dan 国 dibaca こく."}:                                                                                                        "外国 is read がいこく (foreign country). 外 is read がい and 国 is read こく.",
	{field: "simulation.explanation", source: "夕方 dibaca ゆうがた (senja). Kata ini bacaan khusus gabungan."}:                                                                                                          "夕方 is read ゆうがた (evening, around dusk). This is a fixed compound reading.",
	{field: "simulation.explanation", source: "ほん (buku) ditulis 本. 木 = pohon; 末 = ujung; 体 = tubuh."}:                                                                                                             "ほん (book) is written 本. 木 = tree; 末 = end; 体 = body.",
	{field: "simulation.explanation", source: "くるま (mobil) ditulis 車. 軍 hanya mirip bentuknya."}:                                                                                                                   "くるま (car) is written 車. 軍 only looks similar.",
	{field: "simulation.explanation", source: "おかね (uang) ditulis お金. Pilihan lain memakai huruf yang tidak berarti uang."}:                                                                                        "おかね (money) is written お金. The other choices use characters that do not mean money.",
	{field: "simulation.explanation", source: "ながい (panjang) ditulis 長い. Pilihan lain bukan tulisan kata ini."}:                                                                                                    "ながい (long) is written 長い. The other choices are not how this word is written.",
	{field: "simulation.explanation", source: "ぺん (pena) ditulis ペン. Tanda handakuten (゜) membuat ヘ menjadi ペ."}:                                                                                                   "ぺん (pen) is written ペン. The handakuten (゜) turns ヘ into ペ.",
	{field: "simulation.explanation", source: "Haus, maka minum air: みずをのむ. たべる = makan; かく = menulis; きく = mendengar."}:                                                                                           "You are thirsty, so you drink water: みずをのむ. たべる = to eat; かく = to write; きく = to listen.",
	{field: "simulation.explanation", source: "Celana terlalu kecil, maka membeli yang lebih besar: おおきい. あかるい = terang; おもい = berat; つめたい = dingin."}:                                                             "The trousers are too small, so you buy bigger ones: おおきい. あかるい = bright; おもい = heavy; つめたい = cold.",
	{field: "simulation.explanation", source: "Meminjam buku di perpustakaan: としょかん. びょういん = rumah sakit; ゆうびんきょく = kantor pos; ぎんこう = bank."}:                                                                     "You borrow books at the library: としょかん. びょういん = hospital; ゆうびんきょく = post office; ぎんこう = bank.",
	{field: "simulation.explanation", source: "から menunjukkan pemberinya, maka kata kerja menerima: もらいました. かりる = meminjam; おくる = mengirim."}:                                                                      "から marks the giver, so the verb is the receiving one: もらいました. かりる = to borrow; おくる = to send.",
	{field: "simulation.explanation", source: "やすみがない berarti tidak punya waktu libur. ぜんぜん dipakai dengan bentuk negatif."}:                                                                                       "やすみがない means there is no time off. ぜんぜん is used with the negative form.",
	{field: "simulation.explanation", source: "Kereta penuh sesak, sehingga tidak bisa duduk: すわる. はしる = berlari; およぐ = berenang; うたう = bernyanyi."}:                                                               "The train was crowded, so you could not sit: すわる. はしる = to run; およぐ = to swim; うたう = to sing.",
	{field: "simulation.explanation", source: "おいしくない berarti tidak enak, sama dengan まずい. Pilihan lain menyebut rasa manis, harga, atau ukuran."}:                                                                 "おいしくない means not tasty, the same as まずい. The other choices mention sweetness, price or size.",
	{field: "simulation.explanation", source: "まいにち berarti setiap hari, jadi tidak ada hari tanpa bertemu teman. Pilihan lain berarti kadang-kadang, belum pernah, atau tidak punya teman."}:                      "まいにち means every day, so there is no day without meeting friends. The other choices mean sometimes, never, or having no friends.",
	{field: "simulation.explanation", source: "Tolong jangan membuang sampah = tidak boleh membuang sampah. Pilihan lain membolehkan, menyuruh memungut, atau soal makan."}:                                        "Please do not throw away trash = you must not throw away trash. The other choices permit it, ask to pick it up, or talk about eating.",
	{field: "simulation.explanation", source: "Bentuk kamus + まえに berarti sebelum melakukan sesuatu. あとで dipakai dengan bentuk た."}:                                                                                "Dictionary form + まえに means before doing something. あとで is used with the た-form.",
	{field: "simulation.explanation", source: "Kemampuan: bentuk kamus + ことができます berarti dapat melakukan."}:                                                                                                        "Ability: dictionary form + ことができます means can do.",
	{field: "simulation.explanation", source: "えきから ちかい berarti dekat dari stasiun. から menunjukkan titik acuan jarak."}:                                                                                            "えきから ちかい means close to the station. から marks the reference point of distance.",
	{field: "simulation.explanation", source: "ので menyatakan alasan: tidur larut malam, jadi pagi ini mengantuk."}:                                                                                                 "ので expresses a reason: went to bed late, so I am sleepy this morning.",
	{field: "simulation.explanation", source: "Bentuk た + ら menyatakan syarat: ふったら, jika hujan turun."}:                                                                                                           "The た-form + ら expresses a condition: ふったら, if it rains.",
	{field: "simulation.explanation", source: "Kata tanya + も + bentuk negatif berarti tidak seorang pun: だれもきませんでした."}:                                                                                            "Question word + も + negative means no one: だれもきませんでした.",
	{field: "simulation.explanation", source: "Meminta izin: bentuk て + もいいですか, bolehkah saya memakai pena ini?"}:                                                                                                  "Asking permission: て-form + もいいですか, may I use this pen?",
	{field: "simulation.explanation", source: "Tujuan pergi ditandai に setelah batang ます: かいにいきます, pergi untuk membeli."}:                                                                                          "The purpose of going is marked with に after the ます-stem: かいにいきます, go to buy.",
	{field: "simulation.explanation", source: "Bentuk ない + で berarti tanpa melakukan: たべないで, pergi tanpa sarapan."}:                                                                                                "The ない-form + で means without doing: たべないで, went without having breakfast.",
	{field: "simulation.explanation", source: "Urutan: あれは わたしが きのう かった ほんです (itu buku yang saya beli kemarin). ★ adalah slot ketiga, かった."}:                                                                       "Order: あれは わたしが きのう かった ほんです (that is the book I bought yesterday). ★ is the third slot, かった.",
	{field: "simulation.explanation", source: "Urutan: あそこで しろい シャツを きて いる ひとは わたしの せんせいです (orang berkemeja putih di sana adalah guru saya). ★ adalah slot ketiga, きて."}:                                           "Order: あそこで しろい シャツを きて いる ひとは わたしの せんせいです (the person wearing a white shirt over there is my teacher). ★ is the third slot, きて.",
	{field: "simulation.explanation", source: "Urutan: ちちは うみで さかなを つる のが すきです (ayah suka memancing ikan di laut). ★ adalah slot ketiga, つる."}:                                                                     "Order: ちちは うみで さかなを つる のが すきです (my father likes fishing at the sea). ★ is the third slot, つる.",
	{field: "simulation.explanation", source: "Urutan: わたしは まだ すしを たべた ことが ありません (saya belum pernah makan sushi). ★ adalah slot ketiga, たべた."}:                                                                     "Order: わたしは まだ すしを たべた ことが ありません (I have never eaten sushi yet). ★ is the third slot, たべた.",
	{field: "simulation.explanation", source: "Cerita tentang kebiasaan setiap pagi, maka bentuk sekarang: さんぽにいきます."}:                                                                                             "The text is about a daily morning habit, so the present form is used: さんぽにいきます.",
	{field: "simulation.explanation", source: "が menyatakan pertentangan: hujan turun, tetapi anjing ingin pergi."}:                                                                                                "が expresses contrast: it was raining, but the dog wanted to go.",
	{field: "simulation.explanation", source: "ので menyatakan alasan: kaki kotor, jadi dicuci sebelum masuk rumah."}:                                                                                                "ので expresses a reason: the feet were dirty, so they were washed before going into the house.",
	{field: "simulation.explanation", source: "Pola ～になる berarti menjadi: たのしいきもちになりました, merasa senang."}:                                                                                                          "The pattern ～になる means to become: たのしいきもちになりました, came to feel happy.",
	{field: "simulation.explanation", source: "約束（やくそく） berarti janji. Pilihan lain bukan bacaan yang benar."}:                                                                                                     "約束（やくそく） means a promise. The other choices are not correct readings.",
	{field: "simulation.explanation", source: "運動（うんどう） berarti berolahraga atau gerak badan."}:                                                                                                                    "運動（うんどう） means exercise or physical activity.",
	{field: "simulation.explanation", source: "病気（びょうき） berarti sakit. Perhatikan bunyi びょう dengan ょ kecil."}:                                                                                                      "病気（びょうき） means illness. Note the sound びょう with a small ょ.",
	{field: "simulation.explanation", source: "忘れる（わすれる） berarti lupa; bentuk て adalah 忘れて."}:                                                                                                                      "忘れる（わすれる） means to forget; its て-form is 忘れて.",
	{field: "simulation.explanation", source: "特別（とくべつ） berarti istimewa atau khusus."}:                                                                                                                            "特別（とくべつ） means special.",
	{field: "simulation.explanation", source: "動物園（どうぶつえん） adalah kebun binatang. 園 dibaca えん."}:                                                                                                                   "動物園（どうぶつえん） is a zoo. 園 is read えん.",
	{field: "simulation.explanation", source: "研究（けんきゅう） berarti penelitian atau mempelajari secara mendalam."}:                                                                                                    "研究（けんきゅう） means research or studying something in depth.",
	{field: "simulation.explanation", source: "りょうり (masakan) ditulis 料理. Pilihan lain memakai huruf yang mirip tetapi salah."}:                                                                                    "りょうり (cooking, dish) is written 料理. The other choices use similar-looking but wrong characters.",
	{field: "simulation.explanation", source: "かいぎ (rapat) ditulis 会議. 合議 dibaca ごうぎ dan artinya berbeda."}:                                                                                                        "かいぎ (meeting) is written 会議. 合議 is read ごうぎ and has a different meaning.",
	{field: "simulation.explanation", source: "あんしん (tenang, lega) ditulis 安心. 安 berarti aman dan 心 berarti hati."}:                                                                                                "あんしん (peace of mind, relief) is written 安心. 安 means safe and 心 means heart.",
	{field: "simulation.explanation", source: "しつもん (pertanyaan) ditulis 質問. 問 memiliki 口 di dalam 門, sedangkan 間 memakai 日."}:                                                                                     "しつもん (question) is written 質問. 問 has 口 inside 門, whereas 間 uses 日.",
	{field: "simulation.explanation", source: "ぷれぜんと ditulis プレゼント. Perhatikan ゼ (ze) dan ト (to) pada ejaan katakana yang benar."}:                                                                                 "ぷれぜんと is written プレゼント. Note ゼ (ze) and ト (to) in the correct katakana spelling.",
	{field: "simulation.explanation", source: "部屋を掃除する berarti membersihkan ruangan. 運転 = mengemudi; 紹介 = memperkenalkan; 予約 = memesan."}:                                                                          "部屋を掃除する means to clean a room. 運転 = driving; 紹介 = introducing; 予約 = reserving.",
	{field: "simulation.explanation", source: "借りた本を返す berarti mengembalikan buku yang dipinjam. 貸す = meminjamkan; 直す = memperbaiki; 売る = menjual."}:                                                               "借りた本を返す means to return a borrowed book. 貸す = to lend; 直す = to fix; 売る = to sell.",
	{field: "simulation.explanation", source: "電車が込む berarti kereta penuh sesak, sehingga tidak bisa duduk. 空く = kosong; 開く = terbuka; 落ちる = jatuh."}:                                                              "電車が込む means the train is crowded, so you cannot sit. 空く = to become empty; 開く = to open; 落ちる = to fall.",
	{field: "simulation.explanation", source: "入院している人をお見舞いに行く berarti menjenguk orang yang dirawat. お祝い = perayaan; お礼 = ucapan terima kasih; お願い = permintaan."}:                                                 "入院している人をお見舞いに行く means to visit someone who is in the hospital. お祝い = a celebration; お礼 = thanks; お願い = a request.",
	{field: "simulation.explanation", source: "発表の前の練習 berarti latihan sebelum presentasi. 注文 = pesanan; 引っ越し = pindah rumah; 散歩 = jalan-jalan."}:                                                                  "発表の前の練習 means practice before a presentation. 注文 = an order; 引っ越し = moving house; 散歩 = a walk.",
	{field: "simulation.explanation", source: "急に berarti tiba-tiba. 必ず = pasti; 特に = terutama; 少しも dipakai dengan bentuk negatif."}:                                                                               "急に means suddenly. 必ず = without fail; 特に = especially; 少しも is used with the negative form.",
	{field: "simulation.explanation", source: "注意する berarti berhati-hati. 紹介 = memperkenalkan; 準備 = menyiapkan; 参加 = ikut serta."}:                                                                                 "注意する means to be careful. 紹介 = to introduce; 準備 = to prepare; 参加 = to participate.",
	{field: "simulation.explanation", source: "手伝う berarti membantu. 習う = belajar dari seseorang; 売る = menjual; 教える = mengajar."}:                                                                                  "手伝う means to help. 習う = to learn from someone; 売る = to sell; 教える = to teach.",
	{field: "simulation.explanation", source: "店が閉まっている berarti toko tutup, yaitu tidak beroperasi saat ini. Pilihan lain berarti ramai, baru, atau sedang diskon."}:                                               "店が閉まっている means the shop is closed, that is, not operating right now. The other choices mean crowded, new, or on sale.",
	{field: "simulation.explanation", source: "お帰りになる adalah bentuk hormat dari 帰る. Maknanya guru sudah pulang. Pilihan lain berarti akan pulang, belum pulang, atau sudah datang."}:                               "お帰りになる is the honorific form of 帰る. It means the teacher has already gone home. The other choices mean will go home, has not gone home, or has already come.",
	{field: "simulation.explanation", source: "簡単ではない berarti tidak mudah, sehingga padanannya adalah 難しい (sulit)."}:                                                                                               "簡単ではない means not easy, so the equivalent is 難しい (difficult).",
	{field: "simulation.explanation", source: "遅刻する berarti terlambat, yaitu tidak tiba tepat waktu: 時間に間に合わなかった."}:                                                                                                "遅刻する means to be late, that is, not to arrive on time: 時間に間に合わなかった.",
	{field: "simulation.explanation", source: "落とす berarti menjatuhkan atau kehilangan karena terjatuh, misalnya dompet. Objek lain pada pilihan tidak cocok."}:                                                    "落とす means to drop or to lose by dropping, for example a wallet. The other objects in the choices do not fit.",
	{field: "simulation.explanation", source: "にぎやか berarti ramai dan penuh orang atau suara, seperti pusat perbelanjaan hari Minggu. Perpustakaan malam hari dan kamar sendirian cenderung sepi."}:                "にぎやか means lively, full of people or noise, like a shopping mall on Sunday. A library at night and a room by yourself tend to be quiet.",
	{field: "simulation.explanation", source: "集まる adalah kata kerja intransitif: orang atau benda berkumpul sendiri. Untuk mengumpulkan sesuatu dipakai 集める."}:                                                    "集まる is an intransitive verb: people or things gather by themselves. To gather something, 集める is used.",
	{field: "simulation.explanation", source: "確かめる berarti memastikan kebenaran sesuatu, misalnya memeriksa apakah pintu sudah dikunci."}:                                                                         "確かめる means to confirm that something is true, for example checking whether the door is locked.",
	{field: "simulation.explanation", source: "Batang kata kerja + やすい berarti mudah dilakukan: 読みやすい (mudah dibaca)."}:                                                                                            "Verb stem + やすい means easy to do: 読みやすい (easy to read).",
	{field: "simulation.explanation", source: "ので menyatakan alasan: karena hujan turun, pertandingan dibatalkan."}:                                                                                                "ので expresses a reason: because it rained, the match was cancelled.",
	{field: "simulation.explanation", source: "Bentuk kamus + ように menyatakan tujuan: 上手になるように, agar menjadi mahir."}:                                                                                               "Dictionary form + ように expresses a purpose: 上手になるように, so that one becomes skilled.",
	{field: "simulation.explanation", source: "Bentuk ば menyatakan syarat: 時間があれば, jika ada waktu. あると biasanya untuk hasil alami, bukan ajakan."}:                                                                 "The ば-form expresses a condition: 時間があれば, if there is time. あると usually describes a natural result, not an invitation.",
	{field: "simulation.explanation", source: "Menerima kebaikan dari guru memakai ていただく: 見ていただきました. あげる dan やる berarti memberi."}:                                                                                 "Receiving a kindness from a teacher uses ていただく: 見ていただきました. あげる and やる mean to give.",
	{field: "simulation.explanation", source: "Kausatif pasif ～させられる berarti dipaksa melakukan sesuatu: 弟は母に掃除させられました, adik disuruh ibu membersihkan kamar."}:                                                      "The causative-passive ～させられる means being made to do something: 弟は母に掃除させられました, my younger brother was made by Mom to clean the room.",
	{field: "simulation.explanation", source: "Alasan yang sudah terjadi memakai bentuk lampau biasa + からです: 止まったからです, karena kereta berhenti."}:                                                                   "A reason that has already happened uses the plain past form + からです: 止まったからです, because the train stopped.",
	{field: "simulation.explanation", source: "Bentuk potensial negatif 持てません berarti tidak sanggup membawa. 持たせる = menyuruh membawa; 持たされる = dipaksa membawa."}:                                                   "The negative potential form 持てません means cannot carry. 持たせる = to make someone carry; 持たされる = to be made to carry.",
	{field: "simulation.explanation", source: "Kabar yang didengar memakai bentuk biasa + そうです: 降るそうです, katanya akan hujan. 降った tidak cocok karena 明日 (besok) belum terjadi."}:                                     "Hearsay uses the plain form + そうです: 降るそうです, I hear it will rain. 降った does not fit because 明日 (tomorrow) has not happened yet.",
	{field: "simulation.explanation", source: "までに menyatakan batas waktu pengumpulan: sampai paling lambat Jumat depan. まで menyatakan kegiatan yang berlangsung terus hingga waktu itu."}:                         "までに expresses a deadline for submission: by next Friday at the latest. まで expresses an activity that continues until that time.",
	{field: "simulation.explanation", source: "Bentuk ない + で berarti tanpa melakukan sesuatu: 食べないで家を出ました, keluar rumah tanpa sarapan."}:                                                                           "The ない-form + で means without doing something: 食べないで家を出ました, left the house without eating breakfast.",
	{field: "simulation.explanation", source: "Batang kata sifat + すぎる berarti terlalu. Sebelum て dipakai batang すぎ: 難しすぎて."}:                                                                                      "い-adjective stem + すぎる means too much. Before て the stem すぎ is used: 難しすぎて.",
	{field: "simulation.explanation", source: "Bentuk た + ほうがいいです berarti sebaiknya melakukan sesuatu: 休んだほうがいい."}:                                                                                                 "The た-form + ほうがいいです means it is better to do something: 休んだほうがいい.",
	{field: "simulation.explanation", source: "Urutan: 私は 日本で 納豆を 食べた ことが ありません (saya belum pernah makan natto di Jepang). ★ adalah slot ketiga, 食べた."}:                                                            "Order: 私は 日本で 納豆を 食べた ことが ありません (I have never eaten natto in Japan). ★ is the third slot, 食べた.",
	{field: "simulation.explanation", source: "Urutan: 私は 将来 日本で 医者に なりたいと 思っています (saya ingin menjadi dokter di Jepang kelak). ★ adalah slot ketiga, 医者に."}:                                                        "Order: 私は 将来 日本で 医者に なりたいと 思っています (I want to become a doctor in Japan in the future). ★ is the third slot, 医者に.",
	{field: "simulation.explanation", source: "Urutan: 雨が 降って いる ので 散歩を やめました (karena sedang hujan, saya membatalkan jalan-jalan). ★ adalah slot kedua, いる."}:                                                      "Order: 雨が 降って いる ので 散歩を やめました (because it was raining, I called off the walk). ★ is the second slot, いる.",
	{field: "simulation.explanation", source: "Urutan: 先生は もう お昼ご飯を 召し上がり ましたか (apakah guru sudah makan siang?). ★ adalah slot ketiga, 召し上がり, bentuk hormat dari 食べる."}:                                            "Order: 先生は もう お昼ご飯を 召し上がり ましたか (has the teacher already had lunch?). ★ is the third slot, 召し上がり, the honorific form of 食べる.",
	{field: "simulation.explanation", source: "やめようかと思いました berarti sempat berpikir untuk membatalkan. 思う cocok dengan pola ～かと思う."}:                                                                                "やめようかと思いました means I briefly thought about calling it off. 思う fits the pattern ～かと思う.",
	{field: "simulation.explanation", source: "Pola ～たり～たりする: 泳いだり、貝を拾ったりしました. Kata kerja akhir adalah する dalam bentuk lampau."}:                                                                                   "The pattern ～たり～たりする: 泳いだり、貝を拾ったりしました. The final verb is する in the past form.",
	{field: "simulation.explanation", source: "Setelah bersenang-senang, tiba-tiba hujan: pertentangan yang tak terduga, maka ところが. ですから = karena itu; たとえば = misalnya; つまり = jadi/yaitu."}:                        "After having fun, it suddenly rained: an unexpected contrast, so ところが. ですから = therefore; たとえば = for example; つまり = in other words.",
	{field: "simulation.explanation", source: "Penutup menyatakan keinginan: また行きたいです, ingin pergi lagi. Pilihan lain tidak sesuai dengan bagian \"次の休みにも\"."}:                                                     "The closing expresses a wish: また行きたいです, I want to go again. The other choices do not match the part \"次の休みにも\".",
	{field: "simulation.explanation", source: "Tempat rapat pindah ke ruang rapat lantai tiga. Dokumen disiapkan oleh Yamamoto, dan ruang lantai dua tidak bisa dipakai."}:                                         "The meeting place has moved to the meeting room on the third floor. The documents are prepared by Yamamoto, and the second-floor room cannot be used.",
	{field: "simulation.explanation", source: "Tanggal 1 sampai 7 perpustakaan tutup. Orang yang batas pengembaliannya jatuh pada masa itu boleh mengembalikan pada tanggal 8 tanpa dianggap terlambat."}:          "The library is closed from the 1st to the 7th. People whose return date falls in that period may return on the 8th without being counted as late.",
	{field: "simulation.explanation", source: "Sakura makan malam bersama teman, pulang larut, tidak perlu dijemput, dan tidak perlu dibuatkan makan malam."}:                                                      "Sakura is having dinner with a friend, will come home late, does not need to be picked up, and does not need dinner prepared.",
	{field: "simulation.explanation", source: "Alasan disebut pada paragraf pertama: nama sayur tidak dimengerti sehingga membeli sambil melihat foto."}:                                                           "The reason is given in the first paragraph: the names of the vegetables were not understood, so the writer bought them while looking at the photos.",
	{field: "simulation.explanation", source: "Paragraf pertama menyebut tidak sempat sarapan dan otak tidak bekerja sampai siang. Berteman dengan tetangga adalah hasil kemudian, bukan alasan awal."}:            "The first paragraph says there was no time for breakfast and the writer's head did not work until noon. Making friends with a neighbor is a later result, not the original reason.",
	{field: "simulation.explanation", source: "Hari pertama banyak orang sehingga sulit berfoto; karena itu hari kedua berangkat pagi-pagi saat kuil sepi."}:                                                       "On the first day there were many people, so it was hard to take photos; therefore on the second day the writer set out early when the shrine was quiet.",
	{field: "simulation.explanation", source: "Pada hari Sabtu kolam renang tutup pukul 18:00. Gym buka sampai pukul 20:00 dan tidak libur pada Sabtu. Gedung olahraga membutuhkan reservasi."}:                    "On Saturday the pool closes at 18:00. The gym is open until 20:00 and is not closed on Saturday. The sports hall requires a reservation.",
	{field: "simulation.explanation", source: "Penonton tidak perlu mendaftar dan masuk gratis; cukup datang langsung ke aula pada hari acara."}:                                                                   "Spectators do not need to register and entry is free; they just come straight to the hall on the day of the event.",
	{field: "simulation.explanation", source: "習慣（しゅうかん） berarti kebiasaan. 習 dibaca しゅう dan 慣 dibaca かん."}:                                                                                                        "習慣（しゅうかん） means a habit. 習 is read しゅう and 慣 is read かん.",
	{field: "simulation.explanation", source: "大切（たいせつ） berarti penting atau berharga."}:                                                                                                                           "大切（たいせつ） means important or precious.",
	{field: "simulation.explanation", source: "紹介（しょうかい） berarti memperkenalkan. Vokal panjang ょう pada しょう."}:                                                                                                      "紹介（しょうかい） means to introduce. Note the long vowel ょう in しょう.",
	{field: "simulation.explanation", source: "泳ぐ（およぐ） berarti berenang; bentuk sopan 泳ぎます（およぎます）. 扇ぐ (あおぐ) berarti mengipasi, ejaannya berbeda."}:                                                                 "泳ぐ（およぐ） means to swim; the polite form is 泳ぎます（およぎます）. 扇ぐ (あおぐ) means to fan, and is spelled differently.",
	{field: "simulation.explanation", source: "自転車（じてんしゃ） berarti sepeda. 電車 dibaca でんしゃ, tetapi 転車 dibaca てんしゃ."}:                                                                                                 "自転車（じてんしゃ） means bicycle. 電車 is read でんしゃ, but 転車 is read てんしゃ.",
	{field: "simulation.explanation", source: "途中（とちゅう） berarti di tengah perjalanan."}:                                                                                                                            "途中（とちゅう） means on the way.",
	{field: "simulation.explanation", source: "都合（つごう） berarti keadaan atau kecocokan jadwal. 都合が悪い = kurang cocok/tidak bisa."}:                                                                                   "都合（つごう） means circumstances or schedule convenience. 都合が悪い = inconvenient / cannot make it.",
	{field: "simulation.explanation", source: "げんき (sehat, bersemangat) ditulis 元気. 気 berarti semangat atau perasaan."}:                                                                                            "げんき (healthy, energetic) is written 元気. 気 means spirit or feeling.",
	{field: "simulation.explanation", source: "ぎんこう (bank) ditulis 銀行. 銀 berarti perak dan 行 dibaca こう dalam kata ini."}:                                                                                           "ぎんこう (bank) is written 銀行. 銀 means silver and 行 is read こう in this word.",
	{field: "simulation.explanation", source: "かいしゃ (perusahaan) ditulis 会社. 社 berarti perusahaan atau kuil."}:                                                                                                     "かいしゃ (company) is written 会社. 社 means company or shrine.",
	{field: "simulation.explanation", source: "ひこうき (pesawat terbang) ditulis 飛行機. 飛 berarti terbang, 行 berarti pergi, 機 berarti mesin."}:                                                                          "ひこうき (airplane) is written 飛行機. 飛 means to fly, 行 means to go, 機 means machine.",
	{field: "simulation.explanation", source: "えあこん ditulis エアコン (AC). Perhatikan ン pada akhir kata, bukan ソ."}:                                                                                                    "えあこん is written エアコン (air conditioner). Note the ン at the end, not ソ.",
	{field: "simulation.explanation", source: "人気がある berarti populer. 予定 = rencana; 約束 = janji; 趣味 = hobi."}:                                                                                                       "人気がある means to be popular. 予定 = a plan; 約束 = a promise; 趣味 = a hobby.",
	{field: "simulation.explanation", source: "電車が止まる berarti kereta berhenti. 払う = membayar; 売る = menjual; 直る = pulih atau diperbaiki."}:                                                                          "電車が止まる means the train stops. 払う = to pay; 売る = to sell; 直る = to be fixed or to recover.",
	{field: "simulation.explanation", source: "ちゃんと berarti dengan benar atau sebagaimana mestinya. ずっと = terus; ぜひ = pasti/sangat ingin; もうすぐ = sebentar lagi."}:                                                  "ちゃんと means properly or as it should be. ずっと = all along; ぜひ = by all means; もうすぐ = very soon.",
	{field: "simulation.explanation", source: "新しい仕事を始める berarti memulai pekerjaan baru. 閉める = menutup; 止める = menghentikan; 決める = memutuskan."}:                                                                    "新しい仕事を始める means to start a new job. 閉める = to close; 止める = to stop; 決める = to decide.",
	{field: "simulation.explanation", source: "旅行の予定を決める berarti menentukan rencana perjalanan. 習慣 = kebiasaan; 会議 = rapat; 機会 = kesempatan."}:                                                                     "旅行の予定を決める means to decide the travel plans. 習慣 = a habit; 会議 = a meeting; 機会 = an opportunity.",
	{field: "simulation.explanation", source: "送る料金 berarti biaya pengiriman. 習慣 = kebiasaan; 理由 = alasan; 約束 = janji."}:                                                                                           "送る料金 means the shipping fee. 習慣 = a habit; 理由 = a reason; 約束 = a promise.",
	{field: "simulation.explanation", source: "約束の時間に遅れて berarti terlambat dari waktu janji, sehingga lawan bicara menunggu 30 menit. 間に合う = sempat tepat waktu."}:                                                 "約束の時間に遅れて means arriving later than the promised time, so the other person waited 30 minutes. 間に合う = to be in time.",
	{field: "simulation.explanation", source: "Ruangan gelap, maka tirai dibuka: 開けましょう. 閉める = menutup, membuat lebih gelap."}:                                                                                     "The room is dark, so the curtains are opened: 開けましょう. 閉める = to close, making it darker.",
	{field: "simulation.explanation", source: "安全です berarti aman, padanannya 危なくありません (tidak berbahaya). Pilihan lain tidak menyatakan keamanan."}:                                                                 "安全です means safe; its equivalent is 危なくありません (not dangerous). The other choices do not express safety.",
	{field: "simulation.explanation", source: "約束を守る berarti menepati janji, yaitu pasti melakukan apa yang dijanjikan."}:                                                                                          "約束を守る means to keep a promise, that is, to surely do what was promised.",
	{field: "simulation.explanation", source: "Vている + ところです berarti sedang melakukan sesuatu saat ini. Pilihan lain berarti sudah selesai, akan makan, atau belum pernah membuat."}:                                "Vている + ところです means is in the middle of doing something right now. The other choices mean already finished, about to eat, or have never made.",
	{field: "simulation.explanation", source: "上手 dan 得意 sama-sama berarti pandai. 苦手 berarti tidak pandai atau kurang suka."}:                                                                                     "上手 and 得意 both mean skilled. 苦手 means not good at or dislikes.",
	{field: "simulation.explanation", source: "慣れる berarti terbiasa dengan sesuatu, misalnya kehidupan di Jepang. Pilihan lain tidak memakai kata ini dengan benar."}:                                              "慣れる means to get used to something, for example life in Japan. The other choices do not use this word correctly.",
	{field: "simulation.explanation", source: "時間が合う berarti jadwal cocok. Untuk bertemu seseorang dipakai 会う, bukan 合う."}:                                                                                         "時間が合う means the schedules match. To meet someone, 会う is used, not 合う.",
	{field: "simulation.explanation", source: "だんだん berarti sedikit demi sedikit, dipakai untuk perubahan bertahap seperti cuaca yang menghangat."}:                                                                "だんだん means little by little, used for gradual changes such as the weather getting warmer.",
	{field: "simulation.explanation", source: "大事な berarti penting. Dokumen penting perlu dijaga agar tidak hilang."}:                                                                                              "大事な means important. Important documents need to be kept safe so they are not lost.",
	{field: "simulation.explanation", source: "おかげで menyatakan sebab yang membawa hasil baik. せいで dipakai untuk hasil buruk."}:                                                                                     "おかげで expresses a cause that led to a good result. せいで is used for a bad result.",
	{field: "simulation.explanation", source: "Vている + うちに berarti selagi/seiring melakukan sesuatu, lalu terjadi perubahan: 勉強しているうちに."}:                                                                           "Vている + うちに means while/as one keeps doing something, a change then happens: 勉強しているうちに.",
	{field: "simulation.explanation", source: "が menghubungkan dua hal yang bertentangan: bisa berbicara, tetapi tidak bisa membaca."}:                                                                             "が connects two contrasting facts: can speak, but cannot read.",
	{field: "simulation.explanation", source: "までに menyatakan batas waktu: sebelum rapat dimulai, fotokopi dokumen terlebih dahulu."}:                                                                              "までに expresses a deadline: before the meeting starts, copy the documents first.",
	{field: "simulation.explanation", source: "Vてしまう menyatakan tindakan yang disesalkan atau selesai tidak sengaja: 忘れてしまいました, terlanjur lupa."}:                                                                  "Vてしまう expresses an action that is regretted or completed unintentionally: 忘れてしまいました, I ended up forgetting.",
	{field: "simulation.explanation", source: "Vてみる berarti mencoba melakukan: 入れてみましょう, mari coba menambahkan garam."}:                                                                                            "Vてみる means to try doing: 入れてみましょう, let's try adding salt.",
	{field: "simulation.explanation", source: "一人ではできません berarti tidak bisa dikerjakan sendirian. Partikel では menunjukkan batasan keadaan."}:                                                                       "一人ではできません means it cannot be done alone. The particle では marks a limiting circumstance.",
	{field: "simulation.explanation", source: "Pola ～なくてもいい berarti tidak perlu melakukan: 行かなくてもいいです."}:                                                                                                           "The pattern ～なくてもいい means you do not have to: 行かなくてもいいです.",
	{field: "simulation.explanation", source: "Karena tidak tahu jalan, saya bertanya di pos polisi: 聞きました. 聞かれる berarti ditanya orang lain."}:                                                                     "Because I did not know the way, I asked at the police box: 聞きました. 聞かれる means being asked by someone else.",
	{field: "simulation.explanation", source: "Vてある menyatakan keadaan hasil tindakan seseorang: 置いてある, tergeletak (ditaruh). 置いてあるのは berarti yang ditaruh di sini."}:                                              "Vてある expresses the resulting state of someone's action: 置いてある, is placed (was put). 置いてあるのは means what has been put here.",
	{field: "simulation.explanation", source: "Bentuk volisional + と思っています menyatakan niat: 働こうと思っています, berniat bekerja."}:                                                                                         "Volitional form + と思っています expresses an intention: 働こうと思っています, I intend to work.",
	{field: "simulation.explanation", source: "ので menyatakan alasan: karena demam, saya tidak masuk kantor. のに dan ても tidak cocok dengan hasil tersebut."}:                                                         "ので expresses a reason: because I had a fever, I did not go to the office. のに and ても do not fit that result.",
	{field: "simulation.explanation", source: "Vてから berarti sejak melakukan sesuatu: 来てから三年, sudah tiga tahun sejak datang."}:                                                                                      "Vてから means since doing something: 来てから三年, three years since coming.",
	{field: "simulation.explanation", source: "Urutan: 先生に 毎日 日記を 書く ように 言われました (guru menyuruh saya menulis buku harian setiap hari). ★ adalah slot ketiga, 書く."}:                                                  "Order: 先生に 毎日 日記を 書く ように 言われました (my teacher told me to write a diary every day). ★ is the third slot, 書く.",
	{field: "simulation.explanation", source: "Urutan: もし 分からない ことが あれば 聞いて ください (jika ada yang tidak dimengerti, tanyakan). ★ adalah slot kedua, ことが."}:                                                           "Order: もし 分からない ことが あれば 聞いて ください (if there is anything you do not understand, please ask). ★ is the second slot, ことが.",
	{field: "simulation.explanation", source: "Urutan: これは 友達が 旅行で 買って くれた お土産です (ini oleh-oleh yang dibelikan teman saat bepergian). ★ adalah slot ketiga, 買って."}:                                                 "Order: これは 友達が 旅行で 買って くれた お土産です (this is a souvenir my friend bought for me on a trip). ★ is the third slot, 買って.",
	{field: "simulation.explanation", source: "Urutan: 来月から 会社の 大阪支店で 働く ことに なりました (mulai bulan depan saya akan bekerja di cabang Osaka). ★ adalah slot keempat, ことに."}:                                            "Order: 来月から 会社の 大阪支店で 働く ことに なりました (starting next month, it has been decided that I will work at the company's Osaka branch). ★ is the fourth slot, ことに.",
	{field: "simulation.explanation", source: "Kalimat yang dikutip dengan と diikuti kata kerja ucapan: と言いました, Tanaka berkata."}:                                                                                  "A sentence quoted with と is followed by a speech verb: と言いました, Tanaka said.",
	{field: "simulation.explanation", source: "Pertunjukan indah, tetapi perjalanan pulang melelahkan: pertentangan, maka しかし. だから = karena itu; たとえば = misalnya; つまり = yaitu."}:                                   "The show was beautiful, but the trip home was tiring: contrast, so しかし. だから = therefore; たとえば = for example; つまり = in other words.",
	{field: "simulation.explanation", source: "いい思い出になる berarti menjadi kenangan yang baik; peristiwa sudah lewat, maka なりました."}:                                                                                   "いい思い出になる means to become a good memory; the event is over, so なりました.",
	{field: "simulation.explanation", source: "つもり diikuti bentuk kamus untuk niat: 行くつもりです, berniat pergi."}:                                                                                                      "つもり follows the dictionary form to express intention: 行くつもりです, I intend to go.",
	{field: "simulation.explanation", source: "Tes yang direncanakan hari Senin dipindah ke hari Rabu karena Senin libur nasional."}:                                                                               "The test planned for Monday has been moved to Wednesday because Monday is a national holiday.",
	{field: "simulation.explanation", source: "Permintaannya ada pada kalimat terakhir: jika tidak bisa, kirim email. Wan sendiri yang tiba di stasiun sekitar pukul enam."}:                                       "The request is in the last sentence: if you cannot, send an email. Wan is the one who arrives at the station around six.",
	{field: "simulation.explanation", source: "Tamu datang pukul tiga, maka ruang rapat harus dirapikan sebelum itu."}:                                                                                             "Guests are coming at three, so the meeting room must be tidied before then.",
	{field: "simulation.explanation", source: "Nenek langganan memuji sapaannya sehingga penulis senang dan mulai bersuara lebih keras."}:                                                                          "The regular grandmother praised the writer's greeting, so the writer was happy and began to speak louder.",
	{field: "simulation.explanation", source: "Kalimat terakhir menyatakan pendapat penulis: jika semua sedikit berhati-hati, kota menjadi bersih. Isi pilihan lain tidak ada atau berlawanan dengan teks."}:       "The last sentence states the writer's opinion: if everyone is a little careful, the town becomes clean. The other choices are not in the text or contradict it.",
	{field: "simulation.explanation", source: "Rin menulis kata yang tidak dimengerti di buku catatan lalu mencarinya sekaligus saat akhir pekan."}:                                                                "Rin writes down words she does not understand in a notebook and looks them up all at once on the weekend.",
	{field: "simulation.explanation", source: "Mahasiswa termasuk dewasa 800 yen, siswa SMA 500 yen, siswa SD 300 yen. Totalnya 1.600 yen. Biaya parkir tidak dihitung karena naik kereta dan bus."}:               "A university student counts as an adult at 800 yen, a high school student 500 yen, an elementary school student 300 yen. The total is 1,600 yen. The parking fee is not counted because they go by train and bus.",
	{field: "simulation.explanation", source: "Kelas roti ada A (Selasa siang) dan C (Sabtu pukul 14:00). Mina bekerja pada siang hari kerja dan sibuk Sabtu pagi, jadi pilihan yang cocok adalah C."}:             "The bread classes are A (Tuesday daytime) and C (Saturday at 14:00). Mina works during weekday daytime and is busy Saturday morning, so the suitable choice is C.",
	{field: "simulation.explanation", source: "店（みせ） berarti toko. Pilihan lain bukan bacaan yang benar dalam kalimat ini."}:                                                                                       "店（みせ） means shop. The other choices are not correct readings in this sentence.",
	{field: "simulation.explanation", source: "有名（ゆうめい） berarti terkenal."}:                                                                                                                                        "有名（ゆうめい） means famous.",
	{field: "simulation.explanation", source: "開ける（あける） berarti membuka; bentuk て adalah 開けて."}:                                                                                                                    "開ける（あける） means to open; its て-form is 開けて.",
	{field: "simulation.explanation", source: "危ない（あぶない） berarti berbahaya."}:                                                                                                                                      "危ない（あぶない） means dangerous.",
	{field: "simulation.explanation", source: "景色（けしき） berarti pemandangan. Bacaan khusus gabungan."}:                                                                                                              "景色（けしき） means scenery. It is a special compound reading.",
	{field: "simulation.explanation", source: "工場（こうじょう） berarti pabrik. Perhatikan bunyi panjang こう dan じょう."}:                                                                                                    "工場（こうじょう） means factory. Note the long sounds こう and じょう.",
	{field: "simulation.explanation", source: "迎える（むかえる） berarti menjemput atau menyambut; batangnya 迎え."}:                                                                                                         "迎える（むかえる） means to meet or welcome; its stem is 迎え.",
	{field: "simulation.explanation", source: "じゅぎょう (pelajaran) ditulis 授業. 授 berarti memberi dan 業 berarti pekerjaan atau pelajaran."}:                                                                           "じゅぎょう (class, lesson) is written 授業. 授 means to give and 業 means work or lesson.",
	{field: "simulation.explanation", source: "せつめい (penjelasan) ditulis 説明. 説 berarti menjelaskan."}:                                                                                                              "せつめい (explanation) is written 説明. 説 means to explain.",
	{field: "simulation.explanation", source: "あつい untuk minuman ditulis 熱い. 暑い dipakai untuk cuaca dan 厚い untuk benda tebal."}:                                                                                    "あつい for a drink is written 熱い. 暑い is used for weather and 厚い for thick things.",
	{field: "simulation.explanation", source: "ちゅうしゃじょう (tempat parkir) ditulis 駐車場. Pilihan lain memakai huruf yang mirip."}:                                                                                      "ちゅうしゃじょう (parking lot) is written 駐車場. The other choices use similar-looking characters.",
	{field: "simulation.explanation", source: "ぱそこん (komputer pribadi) ditulis パソコン dalam katakana."}:                                                                                                              "ぱそこん (personal computer) is written パソコン in katakana.",
	{field: "simulation.explanation", source: "試験の準備をする berarti mempersiapkan ujian. 注意 = hati-hati; 運動 = olahraga; 紹介 = perkenalan."}:                                                                             "試験の準備をする means to prepare for an exam. 注意 = caution; 運動 = exercise; 紹介 = introduction.",
	{field: "simulation.explanation", source: "Menanyakan jalan di pos polisi: 交番. 空港 = bandara; 工場 = pabrik; 銀行 = bank."}:                                                                                         "You ask for directions at a police box: 交番. 空港 = airport; 工場 = factory; 銀行 = bank.",
	{field: "simulation.explanation", source: "時間がない berarti tidak ada waktu. 気持ち = perasaan; 場所 = tempat; 経験 = pengalaman."}:                                                                                      "時間がない means there is no time. 気持ち = feeling; 場所 = place; 経験 = experience.",
	{field: "simulation.explanation", source: "荷物を送る berarti mengirim barang. 払う = membayar; 拾う = memungut; 建てる = membangun."}:                                                                                     "荷物を送る means to send a package. 払う = to pay; 拾う = to pick up; 建てる = to build.",
	{field: "simulation.explanation", source: "電気が消える berarti lampu padam sendiri. 落とした dan 止めた bersifat transitif, 閉まった untuk pintu."}:                                                                            "電気が消える means the light goes out by itself. 落とした and 止めた are transitive, and 閉まった is for doors.",
	{field: "simulation.explanation", source: "気温が低くなる berarti suhu menurun. 弱い = lemah; 薄い = tipis; 狭い = sempit."}:                                                                                                "気温が低くなる means the temperature drops. 弱い = weak; 薄い = thin; 狭い = narrow.",
	{field: "simulation.explanation", source: "間違いを直す berarti memperbaiki kesalahan. 戻す = mengembalikan ke tempat; 返す = mengembalikan milik orang; 動かす = menggerakkan."}:                                           "間違いを直す means to correct a mistake. 戻す = to put back; 返す = to return something; 動かす = to move.",
	{field: "simulation.explanation", source: "ちょうど berarti tepat pada saat itu. だんだん = sedikit demi sedikit; ずっと = terus; ぜひ = sangat ingin."}:                                                                    "ちょうど means just at that moment. だんだん = gradually; ずっと = all along; ぜひ = by all means.",
	{field: "simulation.explanation", source: "無理です berarti tidak mungkin dilakukan, sama dengan できません."}:                                                                                                          "無理です means it cannot be done, the same as できません.",
	{field: "simulation.explanation", source: "そうです (kabar yang didengar) sama dengan と聞きました. Pilihan lain mengubah waktu atau isi kabar."}:                                                                        "そうです (hearsay) is the same as と聞きました. The other choices change the time or the content of the news.",
	{field: "simulation.explanation", source: "おいしい = 味がいい; 安い = 値段が安い. Pilihan lain mengubah harga atau rasa."}:                                                                                                   "おいしい = 味がいい (tastes good); 安い = 値段が安い (the price is low). The other choices change the price or the taste.",
	{field: "simulation.explanation", source: "注意される berarti diperingatkan guru, yaitu dikatakan agar berhati-hati."}:                                                                                              "注意される means being warned by the teacher, that is, being told to be careful.",
	{field: "simulation.explanation", source: "経験 berarti pengalaman; 経験がある = pernah mengalami. Pilihan lain tidak memakai kata ini dengan wajar."}:                                                                "経験 means experience; 経験がある = to have experience. The other choices do not use the word naturally.",
	{field: "simulation.explanation", source: "続ける adalah kata kerja transitif: melanjutkan sesuatu. Untuk hal yang berlanjut sendiri dipakai 続く."}:                                                                "続ける is transitive: to continue doing something. For something that goes on by itself, 続く is used.",
	{field: "simulation.explanation", source: "しばらく berarti sebentar atau beberapa saat."}:                                                                                                                         "しばらく means for a while.",
	{field: "simulation.explanation", source: "親切 berarti ramah dan suka membantu; dipakai untuk sifat orang."}:                                                                                                    "親切 means kind and helpful; it describes a person's character.",
	{field: "simulation.explanation", source: "Bentuk biasa + ほど menyatakan tingkat: できるほど簡単, semudah itu sehingga anak pun bisa."}:                                                                                "Plain form + ほど expresses degree: できるほど簡単, so easy that even a child can do it.",
	{field: "simulation.explanation", source: "Bentuk て + みたい berarti ingin mencoba melakukan: 見てみたい."}:                                                                                                            "The て-form + みたい means want to try doing: 見てみたい.",
	{field: "simulation.explanation", source: "つもり diikuti bentuk kamus untuk niat: 寝るつもりです."}:                                                                                                                     "つもり follows the dictionary form to express intention: 寝るつもりです.",
	{field: "simulation.explanation", source: "Kausatif pasif ～させられる berarti dipaksa melakukan: 食べさせられました."}:                                                                                                       "The causative-passive ～させられる means being made to do: 食べさせられました.",
	{field: "simulation.explanation", source: "Batang kata kerja + にくい berarti sulit dilakukan: 読みにくい."}:                                                                                                           "Verb stem + にくい means hard to do: 読みにくい.",
	{field: "simulation.explanation", source: "Perbandingan: bentuk kamus + より: 食事をするより."}:                                                                                                                         "Comparison: dictionary form + より: 食事をするより.",
	{field: "simulation.explanation", source: "Subjeknya 先生 yang memberi kebaikan kepada saya: ～てくださる. いただく dan もらう memakai に, あげる arahnya terbalik."}:                                                             "The subject 先生 does a favor for me: ～てくださる. いただく and もらう take に, and あげる reverses the direction.",
	{field: "simulation.explanation", source: "Bentuk た + 場合は berarti dalam hal terjadi: jika hujan, acara olahraga dibatalkan."}:                                                                                  "Past form + 場合は means in case ...: if it rains, the sports day is cancelled.",
	{field: "simulation.explanation", source: "Kata benda + のように berarti seperti ...: 日本人のように話す, berbicara seperti orang Jepang."}:                                                                                 "Noun + のように means like ...: 日本人のように話す, speaks like a Japanese person.",
	{field: "simulation.explanation", source: "Bentuk た + ばかり berarti baru saja: 来たばかり."}:                                                                                                                          "The past form + ばかり means just did: 来たばかり.",
	{field: "simulation.explanation", source: "Bentuk rendah hati お＋batang＋する: お持ちしましょうか, perlu saya bawakan?"}:                                                                                                    "The humble form お + stem + する: お持ちしましょうか, shall I carry it for you?",
	{field: "simulation.explanation", source: "Bentuk kamus + ように menyatakan tujuan untuk hal yang tidak dikendalikan: 治るように. 治す bersifat transitif."}:                                                             "Dictionary form + ように expresses a purpose for something outside one's control: 治るように. 治す is transitive.",
	{field: "simulation.explanation", source: "うえに berarti selain itu: murah dan juga kuat."}:                                                                                                                      "うえに means in addition: cheap and also sturdy.",
	{field: "simulation.explanation", source: "Urutan: 昨日、駅で 私に 道を 聞いた 人は 田中さんの お兄さんでした (orang yang bertanya jalan kepada saya kemarin adalah kakak Tanaka). ★ adalah slot ketiga, 聞いた."}:                          "Order: 昨日、駅で 私に 道を 聞いた 人は 田中さんの お兄さんでした (the person who asked me the way at the station yesterday was Tanaka's older brother). ★ is the third slot, 聞いた.",
	{field: "simulation.explanation", source: "Urutan: 山田さんは 来月から 国へ 帰る ことに なりました (Yamada akan pulang ke negaranya mulai bulan depan). ★ adalah slot ketiga, 帰る."}:                                                 "Order: 山田さんは 来月から 国へ 帰る ことに なりました (it has been decided that Yamada will return to his country from next month). ★ is the third slot, 帰る.",
	{field: "simulation.explanation", source: "Urutan: 日本語が 上手に なる ように 毎日 練習しています (saya berlatih setiap hari agar bahasa Jepang saya mahir). ★ adalah slot ketiga, なる."}:                                           "Order: 日本語が 上手に なる ように 毎日 練習しています (I practice every day so that my Japanese gets better). ★ is the third slot, なる.",
	{field: "simulation.explanation", source: "Urutan: 明日は どうしても 朝六時に 起きなければ なりません (besok saya harus bangun pukul enam pagi). ★ adalah slot ketiga, 起きなければ."}:                                                      "Order: 明日は どうしても 朝六時に 起きなければ なりません (tomorrow I absolutely have to get up at six). ★ is the third slot, 起きなければ.",
	{field: "simulation.explanation", source: "バスに乗ろうかと迷いました berarti bimbang apakah akan naik bus. ～ようかと迷う adalah pola yang wajar."}:                                                                               "バスに乗ろうかと迷いました means hesitated over whether to take the bus. ～ようかと迷う is a natural pattern.",
	{field: "simulation.explanation", source: "お茶をいただく adalah bentuk rendah hati untuk menerima teh. くださる = pihak lain memberi; さしあげる = saya memberi."}:                                                            "お茶をいただく is the humble form for receiving tea. くださる = the other person gives; さしあげる = I give.",
	{field: "simulation.explanation", source: "Setelah hari yang menyenangkan, tersesat dalam perjalanan pulang: pertentangan, maka けれども. ですから = karena itu; たとえば = misalnya; そして = dan."}:                         "After an enjoyable day, getting lost on the way back: contrast, so けれども. ですから = therefore; たとえば = for example; そして = and.",
	{field: "simulation.explanation", source: "Penutup menyatakan perasaan penulis: また来たいと思いました."}:                                                                                                                 "The closing states the writer's feeling: また来たいと思いました, I thought I wanted to come again.",
	{field: "simulation.explanation", source: "Mulai minggu depan jadwal sampah menjadi Selasa dan Jumat, dikeluarkan sebelum pukul 08.00. Pilihan lain tidak sesuai pengumuman."}:                                 "From next week, burnable trash is collected on Tuesday and Friday and must be put out by 8 a.m. The other choices do not match the notice.",
	{field: "simulation.explanation", source: "Orang yang tidak bisa hadir harus menghubungi Tanaka paling lambat hari Rabu."}:                                                                                     "People who cannot come must contact Tanaka by Wednesday.",
	{field: "simulation.explanation", source: "Dokumen sudah diletakkan oleh Sato, jadi Yamamoto tidak perlu melakukannya. Menata meja, menyiapkan teh, dan menyalakan AC adalah tugasnya."}:                       "Sato has already put the documents on the desk, so Yamamoto does not need to. Arranging desks, preparing tea and turning on the air conditioner are his tasks.",
	{field: "simulation.explanation", source: "Penulis senang karena seorang kakek mengucapkan terima kasih, lalu ingin terus melanjutkan."}:                                                                       "The writer was happy that an old man thanked them, and wanted to keep going.",
	{field: "simulation.explanation", source: "Sang ibu menjawab bahwa kereta bergetar karena berjalan di atas rel."}:                                                                                              "The mother answered that the train shakes because it runs on rails.",
	{field: "simulation.explanation", source: "Yamashita mengajak membuat kue bersama pada hari Minggu di rumahnya; bahan dibelikan olehnya."}:                                                                     "Yamashita invites Lin to bake a cake together on Sunday at her house; she will buy the ingredients.",
	{field: "simulation.explanation", source: "A diadakan pagi hari, B hari Selasa dan Kamis, D untuk siswa SMP. Hanya C yang sesuai: Senin dan Jumat siang, 400 yen."}:                                            "A is held in the morning, B on Tuesday and Thursday, and D is for junior high students. Only C fits: Monday and Friday afternoon, 400 yen.",
	{field: "simulation.explanation", source: "15 adalah hari poin 3 kali. Belanja 2.000 yen = 20 × 3 = 60 poin; minuman keras tidak dihitung."}:                                                                   "The 15th is a triple-points day. 2,000 yen of shopping = 20 × 3 = 60 points; alcohol is excluded.",
	{field: "simulation.explanation", source: "午後（ごご） berarti sore hari, setelah tengah hari."}:                                                                                                                    "午後（ごご） means afternoon, after noon.",
	{field: "simulation.explanation", source: "試合（しあい） berarti pertandingan."}:                                                                                                                                     "試合（しあい） means a match or game.",
	{field: "simulation.explanation", source: "荷物（にもつ） berarti barang bawaan."}:                                                                                                                                    "荷物（にもつ） means luggage or baggage.",
	{field: "simulation.explanation", source: "季節（きせつ） berarti musim."}:                                                                                                                                            "季節（きせつ） means season.",
	{field: "simulation.explanation", source: "相談（そうだん） berarti berkonsultasi."}:                                                                                                                                   "相談（そうだん） means to consult.",
	{field: "simulation.explanation", source: "貸す（かす） berarti meminjamkan; bentuk て adalah 貸して. 借りる (かりる) berarti meminjam."}:                                                                                      "貸す（かす） means to lend; its て-form is 貸して. 借りる (かりる) means to borrow.",
	{field: "simulation.explanation", source: "暗い（くらい） berarti gelap. 黒い = くろい (hitam); 嫌い = きらい (tidak suka); 辛い = からい (pedas)."}:                                                                                 "暗い（くらい） means dark. 黒い = くろい (black); 嫌い = きらい (dislike); 辛い = からい (spicy).",
	{field: "simulation.explanation", source: "けいかく (rencana) ditulis 計画. 計 berarti menghitung dan 画 berarti gambar atau rencana."}:                                                                                "けいかく (plan) is written 計画. 計 means to measure and 画 means picture or plan.",
	{field: "simulation.explanation", source: "じこ (kecelakaan) ditulis 事故. Pilihan lain memakai huruf yang mirip."}:                                                                                                "じこ (accident) is written 事故. The other choices use similar-looking characters.",
	{field: "simulation.explanation", source: "あたたかい untuk makanan atau minuman ditulis 温かい. 暖かい dipakai untuk cuaca atau ruangan."}:                                                                               "あたたかい for food or drinks is written 温かい. 暖かい is used for weather or rooms.",
	{field: "simulation.explanation", source: "はこ (kotak) ditulis 箱. 相, 想, dan 湘 hanya mirip bentuknya."}:                                                                                                          "はこ (box) is written 箱. 相, 想 and 湘 only look similar.",
	{field: "simulation.explanation", source: "すぽーつ (olahraga) ditulis スポーツ dalam katakana."}:                                                                                                                      "すぽーつ (sports) is written スポーツ in katakana.",
	{field: "simulation.explanation", source: "Dompet dimasukkan ke dalam tas: かばんの中. ボタン = kancing; ベルト = ikat pinggang; ガラス = kaca."}:                                                                            "The wallet is put inside a bag: かばんの中. ボタン = button; ベルト = belt; ガラス = glass.",
	{field: "simulation.explanation", source: "ゆっくり berarti dengan santai. はっきり = jelas; しっかり = kuat/teguh; ぴったり = pas."}:                                                                                          "ゆっくり means leisurely. はっきり = clearly; しっかり = firmly; ぴったり = exactly fitting.",
	{field: "simulation.explanation", source: "熱を出す berarti demam."}:                                                                                                                                               "熱を出す means to run a fever.",
	{field: "simulation.explanation", source: "仲がいい berarti akrab."}:                                                                                                                                               "仲がいい means to be on good terms.",
	{field: "simulation.explanation", source: "写真を撮る berarti mengambil foto. 取る = mengambil; 打つ = memukul; 引く = menarik."}:                                                                                         "写真を撮る means to take a photo. 取る = to take; 打つ = to hit; 引く = to pull.",
	{field: "simulation.explanation", source: "会議の資料を作る berarti membuat dokumen rapat. 趣味 = hobi; 経験 = pengalaman; 予約 = reservasi."}:                                                                               "会議の資料を作る means to make materials for a meeting. 趣味 = hobby; 経験 = experience; 予約 = reservation.",
	{field: "simulation.explanation", source: "遠足が中止になる berarti darmawisata dibatalkan. 禁止 = larangan."}:                                                                                                           "遠足が中止になる means the field trip is cancelled. 禁止 = prohibition.",
	{field: "simulation.explanation", source: "出かけている berarti sedang pergi, jadi tidak ada di sini."}:                                                                                                              "出かけている means is out, so he is not here.",
	{field: "simulation.explanation", source: "休み berarti tutup, sama dengan tidak buka."}:                                                                                                                         "休み means closed, the same as not open.",
	{field: "simulation.explanation", source: "遅れる = 間に合わない: tidak tiba tepat waktu."}:                                                                                                                             "遅れる = 間に合わない: did not arrive on time.",
	{field: "simulation.explanation", source: "得意 berarti pandai, sama dengan 上手. 苦手 adalah kebalikannya."}:                                                                                                        "得意 means good at, the same as 上手. 苦手 is the opposite.",
	{field: "simulation.explanation", source: "集める adalah kata kerja transitif: mengumpulkan benda, seperti perangko."}:                                                                                            "集める is transitive: to collect things, such as stamps.",
	{field: "simulation.explanation", source: "ぜひ menyatakan keinginan kuat atau ajakan: ぜひ～てください."}:                                                                                                               "ぜひ expresses strong wish or invitation: ぜひ～てください.",
	{field: "simulation.explanation", source: "そろそろ berarti sudah hampir waktunya melakukan sesuatu."}:                                                                                                             "そろそろ means it is almost time to do something.",
	{field: "simulation.explanation", source: "片づける berarti membereskan atau merapikan tempat atau barang."}:                                                                                                       "片づける means to tidy up a place or things.",
	{field: "simulation.explanation", source: "Pasif: 先生にすすめられた本 berarti buku yang dianjurkan guru kepada saya."}:                                                                                                  "Passive: 先生にすすめられた本 means the book recommended to me by my teacher.",
	{field: "simulation.explanation", source: "Bentuk kamus + ことにしている menyatakan kebiasaan yang diputuskan sendiri."}:                                                                                              "Dictionary form + ことにしている expresses a self-decided habit.",
	{field: "simulation.explanation", source: "Kata sifat bentuk kamus menerangkan kata benda: 地震が多い国."}:                                                                                                           "An adjective in dictionary form modifies a noun: 地震が多い国.",
	{field: "simulation.explanation", source: "のに menyatakan pertentangan yang tak terduga: sibuk, tetapi tetap tersenyum."}:                                                                                       "のに expresses unexpected contrast: busy, yet always smiling.",
	{field: "simulation.explanation", source: "Ayah memberi kebaikan kepada saya: ～てくれる. もらう memakai に, あげる arahnya terbalik."}:                                                                                    "Father did a favor for me: ～てくれる. もらう takes に, and あげる reverses the direction.",
	{field: "simulation.explanation", source: "Bentuk ている + うちに berarti selagi masih dalam keadaan itu: selagi anak tidur."}:                                                                                       "ている + うちに means while the situation lasts: while the child is sleeping.",
	{field: "simulation.explanation", source: "Pola ～ば～ほど berarti semakin ... semakin ...: 覚えれば覚えるほど."}:                                                                                                            "The pattern ～ば～ほど means the more ... the more ...: 覚えれば覚えるほど.",
	{field: "simulation.explanation", source: "Bentuk biasa + はずです menyatakan dugaan kuat: 治るはずです, seharusnya sembuh."}:                                                                                            "Plain form + はずです expresses a strong expectation: 治るはずです, it should get better.",
	{field: "simulation.explanation", source: "Bentuk kamus + ために menyatakan tujuan: 野球選手になるために."}:                                                                                                                 "Dictionary form + ために expresses purpose: 野球選手になるために.",
	{field: "simulation.explanation", source: "Bentuk kamus + ときは berarti ketika: kalau akan terlambat, telepon."}:                                                                                                 "Dictionary form + ときは means when: if you will be late, call.",
	{field: "simulation.explanation", source: "Bentuk hormat untuk 来る adalah いらっしゃる. まいる dan 申し上げる bersifat merendah."}:                                                                                            "The honorific form of 来る is いらっしゃる. まいる and 申し上げる are humble.",
	{field: "simulation.explanation", source: "Permintaan sopan: ～てもらえませんか."}:                                                                                                                                      "A polite request: ～てもらえませんか.",
	{field: "simulation.explanation", source: "Bentuk た + まま berarti tetap dalam keadaan itu: tidur dengan jendela terbuka."}:                                                                                      "The past form + まま means leaving things as they are: fell asleep with the window open.",
	{field: "simulation.explanation", source: "Urutan: 熱が あるなら、早く 病院へ 行った ほうが いいです (kalau demam, sebaiknya segera ke rumah sakit). ★ adalah slot ketiga, 行った."}:                                                    "Order: 熱が あるなら、早く 病院へ 行った ほうが いいです (if you have a fever, you should go to the hospital soon). ★ is the third slot, 行った.",
	{field: "simulation.explanation", source: "Urutan: 私は 静かな 音楽を 聞き ながら 勉強します (saya belajar sambil mendengarkan musik yang tenang). ★ adalah slot ketiga, 聞き."}:                                                   "Order: 私は 静かな 音楽を 聞き ながら 勉強します (I study while listening to quiet music). ★ is the third slot, 聞き.",
	{field: "simulation.explanation", source: "Urutan: 田中さんに もし 会ったら お礼を 言おうと 思っています (kalau bertemu Tanaka, saya berniat mengucapkan terima kasih). ★ adalah slot ketiga, お礼を."}:                                   "Order: 田中さんに もし 会ったら お礼を 言おうと 思っています (if I meet Mr. Tanaka, I intend to thank him). ★ is the third slot, お礼を.",
	{field: "simulation.explanation", source: "Urutan: ここは 駐車禁止なので 車を とめては いけません (di sini dilarang parkir, jadi tidak boleh memarkir mobil). ★ adalah slot ketiga, とめては."}:                                         "Order: ここは 駐車禁止なので 車を とめては いけません (parking is prohibited here, so you must not park). ★ is the third slot, とめては.",
	{field: "simulation.explanation", source: "Bentuk て + みたい berarti ingin mencoba: 作ってみたい."}:                                                                                                                     "The て-form + みたい means want to try: 作ってみたい.",
	{field: "simulation.explanation", source: "Awalnya tidak bisa, tetapi berlatih setiap hari: pertentangan, maka でも."}:                                                                                           "At first she could not, but she practiced daily: contrast, so でも.",
	{field: "simulation.explanation", source: "Mengundang teman dan menjamu makanan: 料理をごちそうしました."}:                                                                                                                "Inviting friends and treating them to a meal: 料理をごちそうしました.",
	{field: "simulation.explanation", source: "Teman menghabiskan semua masakan sebagai kebaikan kepada penulis: 食べてくれました."}:                                                                                       "The friends finishing all the food was a favor to the writer: 食べてくれました.",
	{field: "simulation.explanation", source: "Pada hari Rabu pukul 09.00–13.00 ruang baca tidak bisa dipakai karena listrik padam."}:                                                                              "On Wednesday from 9:00 to 13:00 the library room cannot be used because of a power outage.",
	{field: "simulation.explanation", source: "Kimura menunggu kabar dari Sato tentang apakah jadwal baru cocok. Itulah yang harus dilakukan pertama."}:                                                            "Kimura is waiting to hear from Sato whether the new time suits him. That is what he should do first.",
	{field: "simulation.explanation", source: "Min menghangatkan kari dan makan sendiri. Nasi sudah ada dan cucian akan diurus oleh ibu asuh."}:                                                                    "Min heats the curry and eats by herself. The rice is ready and the host mother will take care of the laundry.",
	{field: "simulation.explanation", source: "Setelah lima tahun, penulis kembali mengikuti festival dan merasa rindu."}:                                                                                          "After five years, the writer joined the festival again and felt nostalgic.",
	{field: "simulation.explanation", source: "Kalimat terakhir: penulis kini memakai surel, bukan telepon, di dalam kereta."}:                                                                                     "The last sentence says the writer now uses email instead of phone calls on the train.",
	{field: "simulation.explanation", source: "Natalie meminta Wan meminjamkan catatan kuliah untuk difotokopi."}:                                                                                                  "Natalie asks Wan to lend her the class notes so she can copy them.",
	{field: "simulation.explanation", source: "Setelah pukul 18.00 tarif setengah harga: dewasa 400 → 200 yen, siswa SD 100 → 50 yen. Totalnya 250 yen."}:                                                          "After 18:00 the fee is half price: adult 400 → 200 yen, elementary student 100 → 50 yen. The total is 250 yen.",
	{field: "simulation.explanation", source: "A dan C melebihi anggaran, B tanpa makan siang. Hanya D yang sesuai: 5.000 yen, makan siang termasuk, selesai pukul 15.30."}:                                        "A and C exceed the budget, and B has no lunch. Only D fits: 5,000 yen, lunch included, ends at 15:30.",
}
